import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"WebAuthn Passkey Dogfood — residentKey + /manage quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/webauthn-passkey-app-resident-key.md","filePath":"quality-reports/auth/webauthn-passkey-app-resident-key.md"}'),r={name:"quality-reports/auth/webauthn-passkey-app-resident-key.md"};function i(s,e,n,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="webauthn-passkey-dogfood-—-residentkey-manage-quality-report" tabindex="-1">WebAuthn Passkey Dogfood — residentKey + <code>/manage</code> quality report <a class="header-anchor" href="#webauthn-passkey-dogfood-—-residentkey-manage-quality-report" aria-label="Permalink to &quot;WebAuthn Passkey Dogfood — residentKey + `/manage` quality report&quot;">​</a></h1><p>Sub-Issue #859 (v1.21-2d) fidelity report for the residentKey + credential management axes of the dogfood app (<code>examples/dogfood-webauthn-passkey-app</code>). Covers the four <code>residentKey</code> values (<code>required</code> / <code>preferred</code> / <code>discouraged</code> / unset), the <code>discoverable</code> flag flow through the RP store, the <code>/manage</code> GET + DELETE surface, and the full lifecycle (register → list → signin → delete → signin) across mock and real drivers.</p><h2 id="residentkey-vocabulary" tabindex="-1">residentKey vocabulary <a class="header-anchor" href="#residentkey-vocabulary" aria-label="Permalink to &quot;residentKey vocabulary&quot;">​</a></h2><p>Three spec values from WebAuthn L3 §5.4.6. <code>residentKey</code> is the RP hint that tells the authenticator whether the credential should be <em>discoverable</em> — stored on the authenticator itself, usable without the RP supplying <code>allowCredentials</code> at signin.</p><table tabindex="0"><thead><tr><th>value</th><th>source</th><th>behaviour</th></tr></thead><tbody><tr><td><code>required</code></td><td>WebAuthn L3 §5.4.6</td><td>Authenticator MUST store the credential (resident-key). Fails when authenticator lacks resident-key storage.</td></tr><tr><td><code>preferred</code></td><td>WebAuthn L3 §5.4.6 (default when Passkey is requested)</td><td>Authenticator SHOULD store the credential; RP accepts fallback to a legacy credential when resident-key storage is unavailable.</td></tr><tr><td><code>discouraged</code></td><td>WebAuthn L3 §5.4.6</td><td>Authenticator MUST NOT consume its resident-key slot even when capable — credential is minted as a legacy (server-side) credential.</td></tr><tr><td>unset</td><td>fallback → <code>requireResidentKey</code> boolean (§5.4.4 legacy)</td><td>The kiwa mock treats an unset <code>residentKey</code> as <code>discouraged</code> unless <code>requireResidentKey=true</code>.</td></tr></tbody></table><h2 id="fidelity-axes-residentkey-manage" tabindex="-1">Fidelity axes (residentKey + <code>/manage</code>) <a class="header-anchor" href="#fidelity-axes-residentkey-manage" aria-label="Permalink to &quot;Fidelity axes (residentKey + `/manage`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-test/auth</code>)</th><th>real (SimpleWebAuthn + Chrome Virtual Authenticator)</th><th>assertion</th></tr></thead><tbody><tr><td>1. Creation — <code>required</code> on resident-key-capable authenticator</td><td>Succeeds; <code>credential.discoverable === true</code></td><td>Succeeds; <code>credential.discoverable === true</code></td><td>Both drivers persist the credential and mark it discoverable.</td></tr><tr><td>2. Creation — <code>required</code> on non-resident-key authenticator</td><td>Throws <code>residentKey=required but authenticator does not have resident key storage</code>; trace <code>errorKind = resident_key_unsupported</code></td><td>SimpleWebAuthn <code>verifyRegistrationResponse</code> throws <code>residentKey requirement not satisfied</code>; 400</td><td>Both surface the failure as a client-visible 400 with a stable error kind.</td></tr><tr><td>3. Creation — <code>preferred</code> on resident-key-capable authenticator</td><td><code>credential.discoverable === true</code> (matches <code>required</code>)</td><td><code>credential.discoverable === true</code></td><td>Preferred on a capable authenticator produces a discoverable credential per §5.4.6.</td></tr><tr><td>4. Creation — <code>discouraged</code> on any authenticator</td><td><code>credential.discoverable === false</code> even on a capable authenticator</td><td><code>credential.discoverable === false</code></td><td>Discouraged clears the flag even when resident-key storage is available.</td></tr><tr><td>5. Discovery — signin with empty <code>allowCredentialIds</code></td><td>Discovers the discoverable credential; assertion succeeds</td><td>Discovers the discoverable credential via Chrome resident-key lookup</td><td>WebAuthn L3 §5.5 step 3 — signin without an RP-provided allowCredentials must fall back to the authenticator&#39;s discoverable set.</td></tr><tr><td>6. Delete — <code>/manage?credentialId=...</code></td><td>Removes from both RP store and kiwa env; subsequent signin fails with <code>no_credentials_registered</code></td><td>Removes from the SimpleWebAuthn-shaped RP store; subsequent signin fails with the same error kind</td><td>Both drivers ensure the credential is gone from every store the authenticator can consult.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/resident-key.spec.ts</code> — 22 tests across 7 describe blocks: <ul><li><code>residentKey axis 1 — creation</code> — 4 tests covering the four <code>residentKey</code> values on both capable and incapable authenticators</li><li><code>residentKey axis 2 — discovery</code> — 3 tests covering empty/omitted/missing <code>allowCredentialIds</code> behaviour</li><li><code>residentKey axis 3 — delete</code> — 3 tests covering delete success, unknown-credential rejection, and post-delete signin failure</li><li><code>/manage route — GET (credential list)</code> — 3 tests covering the base list, the <code>?discoverable=true|false</code> filter, and the empty-store path</li><li><code>/manage route — DELETE (credential revoke)</code> — 5 tests covering single-credential delete, 404 on unknown id, 400 on missing param, <code>?confirm=true</code> clear-all, and empty-store clear-all</li><li><code>/manage route — full lifecycle</code> — 1 parameterised test that walks register → list → signin (discovery) → delete → signin (empty) in one go</li><li><code>toCredentialSummary — projection helper</code> — 1 test proving the summary drops <code>publicKey</code> while preserving the management-visible fields</li><li><code>real adapter — env-missing coverage for /manage</code> — 2 tests proving the real adapter&#39;s list/delete still work in the env-missing state (they touch the in-memory store, not Chrome)</li></ul></li><li><code>tests/e2e/passkey-full-flow.spec.ts</code> — 2 Playwright + Chrome Virtual Authenticator tests covering the register → list → signin (discovery) → delete → signin (empty) lifecycle plus the clear-all path</li></ul><h2 id="route-handler-surface-sub-issue-859" tabindex="-1">Route-handler surface (Sub-Issue #859) <a class="header-anchor" href="#route-handler-surface-sub-issue-859" aria-label="Permalink to &quot;Route-handler surface (Sub-Issue #859)&quot;">​</a></h2><p>Both <code>/manage</code> methods accept query params for filtering + confirmation:</p><ul><li><code>GET /manage</code> — returns every persisted credential summary</li><li><code>GET /manage?discoverable=true</code> — returns only discoverable credentials</li><li><code>GET /manage?discoverable=false</code> — returns only legacy credentials</li><li><code>DELETE /manage?credentialId=...</code> — removes the credential; 404 when the id does not exist</li><li><code>DELETE /manage?confirm=true</code> — clears every credential (used by management-UI &quot;Revoke all&quot;); returns <code>deleted: false</code> when the store was already empty</li><li><code>DELETE /manage</code> (no query) — returns 400 <code>missing_credential_id</code></li></ul><h2 id="http-status-mapping" tabindex="-1">HTTP status mapping <a class="header-anchor" href="#http-status-mapping" aria-label="Permalink to &quot;HTTP status mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>operation</th><th>HTTP status</th><th>error field</th></tr></thead><tbody><tr><td><code>GET /manage</code> — succeeds</td><td>200</td><td>(n/a)</td></tr><tr><td><code>DELETE /manage?credentialId=&lt;known&gt;</code> — succeeds</td><td>200</td><td>(n/a)</td></tr><tr><td><code>DELETE /manage?credentialId=&lt;unknown&gt;</code></td><td>404</td><td><code>credential_not_found</code></td></tr><tr><td><code>DELETE /manage</code> (no query)</td><td>400</td><td><code>missing_credential_id</code></td></tr><tr><td><code>DELETE /manage?confirm=true</code> — succeeds</td><td>200</td><td>(n/a)</td></tr><tr><td><code>POST /register</code> with <code>residentKey=required</code> on non-resident-key auth</td><td>400</td><td><code>register_failed</code> (message <code>residentKey=required</code>)</td></tr></tbody></table><h2 id="scope-boundaries" tabindex="-1">Scope boundaries <a class="header-anchor" href="#scope-boundaries" aria-label="Permalink to &quot;Scope boundaries&quot;">​</a></h2><ul><li><code>/manage</code> does not require caller authentication because the dogfood app is single-user. A production RP would gate <code>/manage</code> behind a session cookie and a fresh <code>webauthn.get</code> assertion (step-up authentication) — this is called out in the route source comment for readers reusing the shape.</li><li>The clear-all path (<code>?confirm=true</code>) is intentionally opt-in behind a query flag so a stray browser request cannot wipe the store.</li><li><code>deleteCredential</code> deletes from both the RP-side <code>WebAuthnServer</code> store and the kiwa env&#39;s authenticator-side registry so the fidelity harness cannot be tricked into a &quot;gone from RP but resident on authenticator&quot; split state.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Real driver — <code>KIWA_WEBAUTHN_REAL_READY=1</code> gate stays unwired here (same status as Sub-Issues #857 + #858); Chrome Virtual Authenticator is exercised through Playwright, not through the <code>makeRealAdapter</code> code path. A future PR wires the two together so the real-driver column above becomes an executed diff rather than a spec-based assertion.</li><li>Cross-user credential leakage — the dogfood store is a flat <code>Map&lt;credentialId, credential&gt;</code>, not scoped by <code>userHandle</code>. A production RP would key by user and filter on that; the SCOPE BOUNDARY note in <code>src/app/manage/route.ts</code> covers this.</li></ul>',18)])])}const y=t(r,[["render",i]]);export{p as __pageData,y as default};
